+export function slugify(title: string, options?: { maxLength?: number }): string {
+  let slug = title
+    .toLowerCase()
+    .replace(/[^\p{L}\p{Nd}\s-]/gu, "")
+    .replace(/\s+/gu, "-")
+    .replace(/^-+|-+$/g, "");
+
+  const maxLength = options?.maxLength;
+  if (maxLength !== undefined && slug.length > maxLength) {
+    const truncated = slug.slice(0, Math.max(0, maxLength));
+    const lastHyphen = truncated.lastIndexOf("-");
+    slug = (lastHyphen > 0 ? truncated.slice(0, lastHyphen) : truncated).replace(/-+$/g, "");
+  }
+
+  return slug;
+}
